<?php require 'admin_bootstrap.php'; $title='Gradebook'; $rows=$pdo->query("SELECT g.assessment,g.score,g.max_score,g.feedback,g.created_at,u.name student,u.student_id,s.code,s.name subject,o.section,f.name faculty FROM gradebook_entries g JOIN users u ON u.id=g.student_id JOIN subject_offerings o ON o.id=g.offering_id JOIN subjects s ON s.id=o.subject_id LEFT JOIN users f ON f.id=o.faculty_id ORDER BY g.created_at DESC LIMIT 200")->fetchAll(); require 'header.php'; admin_flash_html(); ?><section class="section"><div class="section-intro"><div><span class="eyebrow">ACADEMIC RECORDS</span><h2>Gradebook Overview</h2><p class="muted">Read-only overview of assessment scores recorded by faculty.</p></div></div><?php if(!$rows):?><div class="info-box">No gradebook entries have been posted yet.</div><?php else:?><div class="table-scroll"><table class="table"><tr><th>Student</th><th>Subject / Section</th><th>Assessment</th><th>Score</th><th>Faculty</th><th>Date</th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['student'])?></b><br><small><?=e($r['student_id']?:'—')?></small></td><td><b><?=e($r['code'])?></b> · <?=e($r['section'])?><br><small><?=e($r['name'])?></small></td><td><?=e($r['assessment'])?></td><td><b><?=e($r['score'])?> / <?=e($r['max_score'])?></b></td><td><?=e($r['faculty']?:'—')?></td><td><?=date('M d, Y',strtotime($r['created_at']))?></td></tr><?php endforeach;?></table></div><?php endif;?></section><?php require 'footer.php'; ?>
